{
  "name": "Yoctopuce I2C 端口模块",
  "name_en": "Yoctopuce I2C Port",
  "manufacturer": "Yoctopuce",
  "description": "用于驱动和管理 Yoctopuce 的 I2C 硬件端口，可在实验系统中与各类 I2C 传感器、执行器或外围模块进行通信。支持设置总线电压与通信模式、发送和接收 I2C 数据、查询响应，以及在设备上上传和运行任务文件。",
  "description_en": "A hardware I2C interface from Yoctopuce used to communicate with I2C sensors, actuators, and peripheral modules in lab setups. It supports configuring bus voltage and communication mode, sending and receiving I2C data, performing query-response transactions, and uploading or running job files on the device.",
  "tag_hints": [
    "I2C communication",
    "USB-to-I2C interface",
    "sensor/peripheral control",
    "bus voltage selection",
    "query-response transactions",
    "job scripting"
  ],
  "actions": [
    {
      "action_name": "auto-set_currentJob",
      "description": "设置当前运行的任务文件",
      "description_en": "Set the current job file."
    },
    {
      "action_name": "auto-set_startupJob",
      "description": "设置上电启动任务文件",
      "description_en": "Set the startup job file."
    },
    {
      "action_name": "auto-set_command",
      "description": "设置命令字符串",
      "description_en": "Set the command string."
    },
    {
      "action_name": "auto-set_protocol",
      "description": "设置通信协议类型",
      "description_en": "Set the communication protocol type."
    },
    {
      "action_name": "auto-set_i2cVoltageLevel",
      "description": "设置 I2C 总线电压等级",
      "description_en": "Set the I2C bus voltage level."
    },
    {
      "action_name": "auto-set_i2cMode",
      "description": "设置 I2C 通信参数",
      "description_en": "Set the I2C communication parameters."
    },
    {
      "action_name": "auto-sendCommand",
      "description": "向 I2C 端口发送底层命令",
      "description_en": "Send a low-level command to the I2C port."
    },
    {
      "action_name": "auto-readLine",
      "description": "从接收缓冲区读取一条消息或一行数据",
      "description_en": "Read one message or line from the receive buffer."
    },
    {
      "action_name": "auto-readMessages",
      "description": "读取与模式匹配的接收消息",
      "description_en": "Read received messages matching a pattern."
    },
    {
      "action_name": "auto-read_seek",
      "description": "设置内部读取流位置",
      "description_en": "Set the internal read stream position."
    },
    {
      "action_name": "auto-read_tell",
      "description": "获取当前读取流位置",
      "description_en": "Get the current read stream position."
    },
    {
      "action_name": "auto-read_avail",
      "description": "获取当前读取位置之后可用的字节数",
      "description_en": "Get the number of bytes available after the current read position."
    },
    {
      "action_name": "auto-queryLine",
      "description": "发送文本行查询并读取回复",
      "description_en": "Send a text line query and read the reply."
    },
    {
      "action_name": "auto-queryHex",
      "description": "发送十六进制二进制查询并读取回复",
      "description_en": "Send a hexadecimal binary query and read the reply."
    },
    {
      "action_name": "auto-uploadJob",
      "description": "上传任务文件定义到设备",
      "description_en": "Upload a job file definition to the device."
    },
    {
      "action_name": "auto-selectJob",
      "description": "加载并启动指定任务文件",
      "description_en": "Load and start the specified job file."
    },
    {
      "action_name": "auto-reset",
      "description": "清空端口缓冲区并重置计数器",
      "description_en": "Clear the port buffer and reset counters."
    },
    {
      "action_name": "auto-i2cSendBin",
      "description": "向指定 I2C 从设备发送二进制数据",
      "description_en": "Send binary data to a specified I2C slave device."
    },
    {
      "action_name": "auto-i2cSendArray",
      "description": "向指定 I2C 从设备发送字节数组",
      "description_en": "Send a byte array to a specified I2C slave device."
    },
    {
      "action_name": "auto-i2cSendAndReceiveBin",
      "description": "向指定 I2C 从设备发送二进制数据并读取返回数据",
      "description_en": "Send binary data to a specified I2C slave device and read back data."
    },
    {
      "action_name": "auto-i2cSendAndReceiveArray",
      "description": "向指定 I2C 从设备发送字节数组并读取返回数据",
      "description_en": "Send a byte array to a specified I2C slave device and read back data."
    },
    {
      "action_name": "auto-writeStr",
      "description": "向 I2C 总线写入文本编码的 I2C 码流",
      "description_en": "Write a text-encoded I2C code stream to the I2C bus."
    },
    {
      "action_name": "auto-writeLine",
      "description": "向 I2C 总线写入一条文本编码的 I2C 码流并释放总线",
      "description_en": "Write a text-encoded I2C code stream to the I2C bus and release the bus."
    },
    {
      "action_name": "auto-writeByte",
      "description": "向 I2C 总线写入单个字节",
      "description_en": "Write a single byte to the I2C bus."
    },
    {
      "action_name": "auto-writeHex",
      "description": "向 I2C 总线写入十六进制字节序列",
      "description_en": "Write a hexadecimal byte sequence to the I2C bus."
    },
    {
      "action_name": "auto-writeBin",
      "description": "向 I2C 总线写入原始二进制缓冲区",
      "description_en": "Write a raw binary buffer to the I2C bus."
    },
    {
      "action_name": "auto-writeArray",
      "description": "向 I2C 总线写入字节数组",
      "description_en": "Write a byte array to the I2C bus."
    },
    {
      "action_name": "auto-nextI2cPort",
      "description": "枚举下一个可访问的 I2C 端口",
      "description_en": "Enumerate the next accessible I2C port."
    }
  ]
}

